/** A piece of the LPC generator (generated by `scripts/inventario-lpc.py`). */
export type InventoryItem = {
  id: string;
  root: string;
  group: string;
  name: string;
  /** All the piece's licenses allow use in the project (CC0, OGA-BY, CC-BY). */
  free: boolean;
  walk: boolean;
  license: string[];
  authors: string[];
  thumb: string | null;
};

/** Head, face and neck (hats, helmets, glasses, earrings, necklaces) and wrists (bracelets). */
const isAccessory = (item: InventoryItem): boolean =>
  item.root === 'headwear' || (item.root === 'arms' && item.group === 'wrists');

/**
 * Which lab page shows each piece. Each piece belongs to ONE page only:
 * the `inventario-regras.test.ts` test checks that none was left without a page or on two.
 */
export const PAGE_RULES: Record<string, (item: InventoryItem) => boolean> = {
  roupas: (item) => ['arms', 'torso', 'legs', 'feet'].includes(item.root) && !isAccessory(item),
  acessorios: isAccessory,
  cabelos: (item) => item.root === 'hair',
  modificadores: (item) => item.root === 'mods' || item.root === 'extras',
  armas: (item) => item.root === 'weapons' || item.root === 'tools',
};
